import{_ as t,o as s,c as a,a5 as i}from"./chunks/framework.DxOcC6on.js";const g=JSON.parse('{"title":"Event Lifecycle","description":"How events flow through hookshot — from external services to Matrix rooms and back","frontmatter":{"title":"Event Lifecycle","description":"How events flow through hookshot — from external services to Matrix rooms and back","audience":["evaluator","developer","operator","contributor","architect"]},"headers":[],"relativePath":"understand/event-lifecycle.md","filePath":"understand/event-lifecycle.md","lastUpdated":1775244963000}'),n={name:"understand/event-lifecycle.md"};function o(r,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="event-lifecycle" tabindex="-1">Event Lifecycle <a class="header-anchor" href="#event-lifecycle" aria-label="Permalink to &quot;Event Lifecycle&quot;">​</a></h1><p>Hookshot processes events in two directions. Inbound: an external service sends a webhook, hookshot transforms it and delivers a Matrix message. Outbound: a user sends a command in a Matrix room, hookshot executes an action on an external service.</p><p>Understanding these two flows explains most of hookshot&#39;s behavior.</p><h2 id="inbound-external-service-to-matrix" tabindex="-1">Inbound: External Service to Matrix <a class="header-anchor" href="#inbound-external-service-to-matrix" aria-label="Permalink to &quot;Inbound: External Service to Matrix&quot;">​</a></h2><p>An external event (GitHub PR opened, GitLab MR merged, JIRA ticket created) becomes a Matrix message through this pipeline:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant EXT as External Service</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant LIS as ListenerService</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant WH as Webhooks.ts&lt;br/&gt;(Express router)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant SVC as Service Router&lt;br/&gt;(e.g. GitHubWebhooksRouter)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant MQ as MessageQueue</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant BR as Bridge.ts</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant CM as ConnectionManager</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant CONN as Connection</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant MS as MatrixSender</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant HS as Homeserver</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    EXT-&gt;&gt;LIS: POST /{service}/webhook</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LIS-&gt;&gt;WH: Route by path prefix</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WH-&gt;&gt;SVC: Delegate to service router</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SVC-&gt;&gt;SVC: Verify signature/secret</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SVC-&gt;&gt;MQ: emit(&quot;{service}.{event}.{action}&quot;, payload)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MQ-&gt;&gt;BR: Deliver to subscriber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BR-&gt;&gt;CM: Find connections for this event</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CM--&gt;&gt;BR: [matching Connection instances]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BR-&gt;&gt;CONN: Call handler (e.g. onIssueCreated)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CONN-&gt;&gt;CONN: Check if event type is enabled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CONN-&gt;&gt;CONN: Format message (emoji, markdown, metadata)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CONN-&gt;&gt;MS: sendMatrixMessage(roomId, content)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MS-&gt;&gt;HS: PUT /_matrix/client/v3/rooms/{roomId}/send/m.room.message</span></span></code></pre></div><h3 id="step-by-step" tabindex="-1">Step by step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step by step&quot;">​</a></h3><p><strong>1. HTTP reception</strong> — External services POST webhooks to hookshot&#39;s HTTP listener. Each service has a dedicated path:</p><table tabindex="0"><thead><tr><th>Path</th><th>Service</th><th>Router</th></tr></thead><tbody><tr><td><code>/github/webhook</code></td><td>GitHub</td><td>GitHubWebhooksRouter</td></tr><tr><td><code>/gitlab</code></td><td>GitLab</td><td>GitLabWebhooksRouter</td></tr><tr><td><code>/jira/events</code></td><td>JIRA</td><td>JiraWebhooksRouter</td></tr><tr><td><code>/figma/webhook</code></td><td>Figma</td><td>FigmaWebhooksRouter</td></tr><tr><td><code>/webhook/{hookId}</code></td><td>Generic webhooks</td><td>GenericWebhooksRouter</td></tr><tr><td><code>/openproject</code></td><td>OpenProject</td><td>OpenProjectWebhooksRouter</td></tr></tbody></table><p><strong>2. Signature verification</strong> — Each service router verifies the webhook is authentic. GitHub uses HMAC-SHA256 via <code>x-hub-signature-256</code>. GitLab uses a secret token header. JIRA and others have their own mechanisms.</p><p><strong>3. Message queue</strong> — The verified payload is emitted to the internal message queue with a topic name following the pattern <code>{service}.{event}.{action}</code>. Examples: <code>github.issues.opened</code>, <code>gitlab.merge_request.close</code>, <code>jira.issue_created</code>.</p><p><strong>4. Bridge dispatch</strong> — <code>Bridge.ts</code> subscribes to all service topics. For each topic, a <code>bindHandlerToQueue</code> call defines: which connection type handles it, how to find the right connection instances, and which method to call.</p><p>There are <strong>45+ handler bindings</strong> across all services:</p><ul><li>GitHub: 15 bindings (issues, PRs, pushes, releases, workflows, discussions)</li><li>GitLab: 12 bindings (merge requests, issues, pushes, tags, wiki, releases, notes)</li><li>JIRA: 5 bindings (issues, versions)</li><li>Figma: 1 binding (comments)</li><li>Feeds: 3 bindings (entry, success, error)</li><li>OpenProject: 2 bindings (work package created, updated)</li><li>ChallengeHound: 1 binding (activity)</li><li>Generic webhooks: 1 binding</li></ul><p><strong>5. Connection lookup</strong> — ConnectionManager finds all Connection instances interested in this event. For GitHub, this means finding all <code>GitHubRepoConnection</code> instances connected to the repository that generated the event.</p><p><strong>6. Handler execution</strong> — The connection&#39;s handler method runs. It checks if the specific event type is enabled (e.g., the user may have disabled <code>push</code> events), formats the message with appropriate emoji and metadata, and sends it.</p><p><strong>7. Matrix delivery</strong> — <code>MatrixSender</code> delivers the message to the Matrix room via the homeserver&#39;s client-server API. Messages are sent as <code>m.room.message</code> events with <code>msgtype: m.notice</code>.</p><h3 id="event-filtering" tabindex="-1">Event filtering <a class="header-anchor" href="#event-filtering" aria-label="Permalink to &quot;Event filtering&quot;">​</a></h3><p>Not all events reach Matrix. Each connection instance has an <code>enableHooks</code> list that controls which event types produce messages. For example, a GitHub repo connection defaults to 13 of 23 possible event types.</p><h3 id="message-format" tabindex="-1">Message format <a class="header-anchor" href="#message-format" aria-label="Permalink to &quot;Message format&quot;">​</a></h3><p>All hookshot messages share a common structure:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;msgtype&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;m.notice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;body&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plain text version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;formatted_body&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;html version&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;format&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org.matrix.custom.html&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;external_url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://link-to-source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;uk.half-shot.matrix-hookshot.{service}.{entity}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;metadata&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;about the source event&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>uk.half-shot.matrix-hookshot.*</code> fields carry structured metadata about the source event (repo, issue, PR, etc.). This enables Matrix clients to build rich displays.</p><h2 id="outbound-matrix-to-external-service" tabindex="-1">Outbound: Matrix to External Service <a class="header-anchor" href="#outbound-matrix-to-external-service" aria-label="Permalink to &quot;Outbound: Matrix to External Service&quot;">​</a></h2><p>A user sends a bot command in a Matrix room. Hookshot parses it, finds the right connection, and executes an action on the external service.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant U as User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant HS as Homeserver</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant BR as Bridge.ts</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant CMD as BotCommands</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant CONN as Connection</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant EXT as External Service</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U-&gt;&gt;HS: Send message: &quot;!gh create &#39;Bug title&#39;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    HS-&gt;&gt;BR: room.message event (appservice API)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BR-&gt;&gt;CMD: Parse command prefix</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CMD-&gt;&gt;CONN: Dispatch to GitHubRepoConnection</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CONN-&gt;&gt;EXT: octokit.issues.create(...)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    EXT--&gt;&gt;CONN: Issue #42 created</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CONN-&gt;&gt;HS: Send confirmation: &quot;Created issue #42&quot;</span></span></code></pre></div><h3 id="step-by-step-1" tabindex="-1">Step by step <a class="header-anchor" href="#step-by-step-1" aria-label="Permalink to &quot;Step by step&quot;">​</a></h3><p><strong>1. Matrix event</strong> — The homeserver delivers the room message to hookshot via the appservice transaction API.</p><p><strong>2. Command parsing</strong> — <code>Bridge.onRoomMessage</code> finds connections in the room. Each connection type defines a command prefix (e.g., <code>!gh</code> for GitHub, <code>!gl</code> for GitLab, <code>!jira</code> for JIRA). The <code>BotCommands</code> system matches the message prefix and dispatches to the correct handler.</p><p><strong>3. Permission check</strong> — Before executing, hookshot checks if the user has permission for this action via the <code>BridgePermissions</code> system.</p><p><strong>4. External API call</strong> — The connection calls the external service API (Octokit for GitHub, axios for GitLab, etc.) using the appropriate credentials.</p><p><strong>5. Confirmation</strong> — The connection sends a response message back to the Matrix room confirming the action.</p><h3 id="available-commands-by-service" tabindex="-1">Available commands by service <a class="header-anchor" href="#available-commands-by-service" aria-label="Permalink to &quot;Available commands by service&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Service</th><th>Prefix</th><th>Commands</th></tr></thead><tbody><tr><td>GitHub</td><td><code>!gh</code></td><td><code>create</code>, <code>close</code>, <code>assign</code>, <code>workflow run</code></td></tr><tr><td>GitLab</td><td><code>!gl</code></td><td><code>create</code>, <code>create-confidential</code>, <code>close</code></td></tr><tr><td>JIRA</td><td><code>!jira</code></td><td><code>create</code>, <code>issue-types</code>, <code>assign</code></td></tr><tr><td>OpenProject</td><td><code>!op</code></td><td><code>create</code>, <code>close</code>, <code>priority</code>, <code>assign</code>, <code>responsible</code></td></tr><tr><td>Setup</td><td><code>!hookshot</code></td><td><code>github repo</code>, <code>gitlab project</code>, <code>jira project</code>, <code>webhook</code>, <code>feed</code>, ...</td></tr></tbody></table><h2 id="emoji-reactions" tabindex="-1">Emoji reactions <a class="header-anchor" href="#emoji-reactions" aria-label="Permalink to &quot;Emoji reactions&quot;">​</a></h2><p>A special outbound flow: hookshot maps Matrix emoji reactions to actions on external services. This is currently implemented for GitHub.</p><table tabindex="0"><thead><tr><th>Emoji</th><th>Action</th></tr></thead><tbody><tr><td>👍 👎 :laugh: 🎉 ❤️ 🚀 👀</td><td>Add GitHub reaction</td></tr><tr><td>🗑️</td><td>Close issue</td></tr><tr><td>✋</td><td>Reopen issue</td></tr><tr><td>✅</td><td>Approve PR</td></tr><tr><td>❌ 🚫</td><td>Request changes on PR</td></tr></tbody></table><h2 id="feed-polling-special-case" tabindex="-1">Feed polling (special case) <a class="header-anchor" href="#feed-polling-special-case" aria-label="Permalink to &quot;Feed polling (special case)&quot;">​</a></h2><p>RSS/Atom feeds don&#39;t use webhooks. Instead, hookshot polls feeds on an interval using a Rust-based feed parser. New entries produce <code>feed.entry</code> events on the message queue, which follow the same Connection handler path as webhook events.</p><h2 id="failure-behavior" tabindex="-1">Failure behavior <a class="header-anchor" href="#failure-behavior" aria-label="Permalink to &quot;Failure behavior&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>System behavior</th></tr></thead><tbody><tr><td>Webhook signature invalid</td><td>HTTP 401 returned, no event processed</td></tr><tr><td>Connection not found for event</td><td>Event silently dropped (logged at debug level)</td></tr><tr><td>Event type disabled on connection</td><td>Event silently dropped</td></tr><tr><td>External API call fails (outbound)</td><td>Error message sent to Matrix room</td></tr><tr><td>Matrix message send fails</td><td>Error logged, message queue handles retry</td></tr><tr><td>Homeserver unreachable</td><td>Messages queued, retried when connection restored</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Concepts:</strong> <a href="./integration-model">Integration Model</a> · <a href="./what-is-hookshot">What is Hookshot</a> · <a href="./trust-and-boundaries">Trust and Boundaries</a> · <a href="./glossary">Glossary</a></p><p><strong>Architecture:</strong> <a href="./../architecture/connections">Connections</a> — Connection lifecycle and state · <a href="./../architecture/state-and-storage">State and Storage</a> — How data persists</p><p><strong>Integrations:</strong> <a href="./../integrations/overview">Overview</a> · <a href="./../integrations/github">GitHub</a> · <a href="./../integrations/generic-webhooks">Generic Webhooks</a></p><p><strong>Reference:</strong> <a href="./../reference/bot-commands">Bot Commands</a> · <a href="./../reference/event-types">Event Types</a> · <a href="./../reference/matrix-spec-map">Matrix Spec Map</a></p><p><strong>Tutorials:</strong> <a href="./../get-started/first-webhook">First Webhook</a> · <a href="./../get-started/first-github-notification">First GitHub Notification</a></p><p><strong>Matrix Spec:</strong> <a href="https://spec.matrix.org/latest/application-service-api/" target="_blank" rel="noreferrer">Application Service API</a> · <a href="https://spec.matrix.org/latest/client-server-api/#room-state" target="_blank" rel="noreferrer">Room State Events</a></p>`,48)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
